// Authoritative check: every key in the project, tag tokens compared against the English
// source ourselves. Does NOT use filter_qa_issues, which Lokalise reindexes asynchronously.
// Locales split into two groups so each response stays small.
const PID = '9933660066825e9a8005c8.58526829';
const GROUPS = [
  ['A', '640,749,10153,10152,10154,753,673,737'],
  ['B', '640,760,708,754,734,767,733,748']
];
const out = [];
for (const g of GROUPS) {
  for (let p = 1; p <= 10; p++) {
    out.push({ json: { project_id: PID, page: p, page_size: 500, group: g[0], lang_ids: g[1] } });
  }
}
return out;

const TARGETS = ['ms','lv','lt','et','th','fr','nl','no','pt','sv','it','da','ko','pl'];
function toks(s) {
  const re = /<\s*\/?\s*[a-zA-Z][^<>]*>/g;
  const o = []; let m;
  while ((m = re.exec(s)) !== null) { o.push(m[0]); }
  return o;
}
function exactsig(s) { return toks(s).join('\u0001'); }
function namesig(s) {
  const o = [];
  for (const t of toks(s)) {
    const mm = /^<\s*(\/?)\s*([a-zA-Z][a-zA-Z0-9]*)/.exec(t);
    if (mm) { o.push((mm[1] ? '/' : '') + mm[2].toLowerCase()); }
  }
  return o.join('|');
}
const per = {};
for (const t of TARGETS) { per[t] = { present: 0, empty: 0, exact_mismatch: 0, name_mismatch: 0 }; }
const seen = {};
let keysWithEn = 0; let noEn = 0; let failedPages = 0;
const sampleBroken = [];
for (const it of $input.all()) {
  const b = it.json || {};
  if (!Array.isArray(b.keys)) { failedPages++; continue; }
  for (const k of b.keys) {
    if (k.is_archived) { continue; }
    let en = null; const tg = [];
    for (const tr of (k.translations || [])) {
      if (typeof tr.translation !== 'string') { continue; }
      const iso = (tr.language_iso || '').toLowerCase();
      if (iso === 'en') { en = tr.translation; continue; }
      if (TARGETS.indexOf(iso) < 0) { continue; }
      tg.push({ iso: iso, v: tr.translation, tid: tr.translation_id });
    }
    if (en === null) { noEn++; continue; }
    if (!seen[k.key_id]) { seen[k.key_id] = 1; keysWithEn++; }
    const xs = exactsig(en); const ns = namesig(en);
    for (const t of tg) {
      const P = per[t.iso];
      if (!t.v.trim()) { P.empty++; continue; }
      P.present++;
      if (exactsig(t.v) !== xs) {
        P.exact_mismatch++;
        if (namesig(t.v) !== ns) { P.name_mismatch++; }
        if (sampleBroken.length < 12) {
          sampleBroken.push({ iso: t.iso, translation_id: t.tid,
            key_id: k.key_id, en_sig: ns, tgt_sig: namesig(t.v) });
        }
      }
    }
  }
}
let totExact = 0; let totName = 0; let totEmpty = 0;
for (const t of TARGETS) { totExact += per[t].exact_mismatch; totName += per[t].name_mismatch; totEmpty += per[t].empty; }
return [{ json: { checked_at: new Date().toISOString(), failed_pages: failedPages,
  keys_with_english_source: keysWithEn, keys_without_english: noEn,
  total_exact_tag_mismatches: totExact, total_structural_mismatches: totName,
  total_empty_translations: totEmpty, per_locale: per, samples: sampleBroken } }];
